<?php require_once __DIR__.'/lib/app.php';require_once __DIR__.'/lib/notify.php';$pdo=db();$msg='';$err='';$requestMonths=max(0,(int)setting('request_months_ahead','2'));$requestMaxDate=date('Y-m-d',strtotime('+'.$requestMonths.' months'));$requestPeriodLabel=$requestMonths.'개월';if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$eid=(int)$_POST['employee_id'];$emp=get_employee($eid);$lt=leave_type((int)$_POST['leave_type_id']);if(!$emp||!$lt)throw new Exception('직원 또는 휴가유형을 확인하세요.');if(setting('employee_auth_mode','phone4')==='phone4' && substr(phone_clean($emp['phone']),-4)!==trim($_POST['phone4']))throw new Exception('휴대폰 뒤 4자리가 일치하지 않습니다.');$start=$_POST['start_date'];$end=$lt['allow_date_range']?$_POST['end_date']:$start;if(!$start||!$end||$end<$start)throw new Exception('신청일자를 확인하세요.');$max=$requestMaxDate;if($start>$max)throw new Exception('신청 가능 기간은 오늘부터 '.$requestPeriodLabel.' 이내입니다. 신청 시작일은 '.date('Y년 m월 d일',strtotime($max)).'까지 선택할 수 있습니다.');daily_capacity_check($eid,$start,$end,(int)$lt['id']);$days=$lt['allow_custom_days']?(float)$_POST['requested_days']:(float)$lt['default_days'];$unit=max(0.01,(float)$lt['min_unit']);if($days<=0||abs(($days/$unit)-round($days/$unit))>0.00001)throw new Exception('사용일수 단위를 확인하세요.');$half=$lt['require_half_option']?trim($_POST['half_option']):'';if($lt['require_half_option']&&!in_array($half,['오전','오후'],true))throw new Exception('오전/오후를 선택하세요.');$deduct=$lt['deduct_enabled']?$days:0;$status=$lt['require_approval']?'pending':'approved';$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO leave_requests(employee_id,leave_type_id,approval_line_id,start_date,end_date,requested_days,deduct_days,half_option,memo,status,approved_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$steps=$lt['require_approval']?approval_steps_for_employee($emp):[];$lineId=!empty($steps[0]['approval_line_id'])?(int)$steps[0]['approval_line_id']:null;$s->execute([$eid,$lt['id'],$lineId,$start,$end,$days,$deduct,$half,trim($_POST['memo']),$status,$status==='approved'?date('Y-m-d H:i:s'):null]);$rid=$pdo->lastInsertId();if($lt['require_approval']){if(!$steps)throw new Exception('적용 가능한 결재선이 없습니다. 관리자에게 문의하세요.');foreach($steps as $i=>$st){$pdo->prepare('INSERT INTO request_approvals(request_id,step_order,approver_employee_id,status) VALUES(?,?,?,?)')->execute([$rid,$st['step_order'],$st['approver_employee_id'],$i===0?'pending':'waiting']);}$pdo->prepare("UPDATE leave_requests SET status='in_approval',current_step=1 WHERE id=?")->execute([$rid]);}$pdo->commit();if($lt['require_approval']&&!empty($steps[0])&&$steps[0]['alimtalk_opt_in'])send_alimtalk('request','employee',$steps[0]['approver_employee_id'],$steps[0]['phone'],['var1'=>trim($emp['name'].' '.$emp['position']),'var2'=>$lt['name'],'var3'=>$start,'var4'=>$end,'var5'=>fmt_days($days),'var6'=>$half?:'-']);if(!$lt['require_approval']&&$emp['alimtalk_opt_in'])send_alimtalk('approved','employee',$eid,$emp['phone'],['var1'=>$emp['name'],'var2'=>$start,'var3'=>$end,'var4'=>fmt_days($days),'var5'=>$lt['name']]);$msg='신청이 정상 접수되었습니다.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}$employees=$pdo->query("SELECT e.*,d.name department_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id WHERE e.is_active=1 ORDER BY e.sort_order,e.id")->fetchAll();$types=$pdo->query('SELECT * FROM leave_types WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();$from=date('Y-m-d');$to=$requestMaxDate;$s=$pdo->prepare("SELECT lr.*,e.name, e.position,lt.name leave_name,lt.color FROM leave_requests lr JOIN employees e ON e.id=lr.employee_id JOIN leave_types lt ON lt.id=lr.leave_type_id WHERE lr.status IN ('in_approval','approved') AND lr.end_date>=? AND lr.start_date<=? ORDER BY lr.start_date,e.sort_order");$s->execute([$from,$to]);$by=[];foreach($s->fetchAll() as $r){foreach(date_range(max($from,$r['start_date']),min($to,$r['end_date'])) as $d)$by[$d][]=$r;}ksort($by);?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title><?=h(setting('org_name','휴가관리'))?></title></head><body><header class="top"><div class="wrap"><div class="brand"><?=h(setting('org_name','휴가관리시스템'))?></div><nav class="nav"><a href="my.php">내 휴가현황</a><a href="admin/login.php">관리자</a></nav></div></header><main class="wrap"><div class="grid"><section class="col6 card"><h1>휴가 사용신청</h1><p class="muted">신청 후 설정된 결재선에 따라 순차 승인됩니다.</p><div class="request-period-guide"><strong>신청 가능 기간</strong><span>신청 시작일 기준 오늘부터 <?=h($requestPeriodLabel)?> 이내</span><small><?=h(date('Y년 m월 d일',strtotime($requestMaxDate)))?>까지 신청할 수 있습니다.</small></div><?php if($msg):?><div class="alert ok"><?=h($msg)?></div><?php endif?><?php if($err):?><div class="alert err"><?=h($err)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>신청자<select name="employee_id" required><option value="">선택하세요</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=h($e['name'].' '.$e['position'].' · '.$e['department_name'])?></option><?php endforeach?></select></label><?php if(setting('employee_auth_mode','phone4')==='phone4'):?><label>휴대폰 뒤 4자리<input name="phone4" maxlength="4" inputmode="numeric" required></label><?php endif?><label>휴가유형<select name="leave_type_id" id="leave_type" required><option value="">선택하세요</option><?php foreach($types as $t):?><option value="<?=$t['id']?>" data-days="<?=$t['default_days']?>" data-custom="<?=$t['allow_custom_days']?>" data-half="<?=$t['require_half_option']?>" data-range="<?=$t['allow_date_range']?>"><?=h($t['name'])?></option><?php endforeach?></select></label><div class="grid"><label class="col6">시작일<input type="date" name="start_date" min="<?=h(date('Y-m-d'))?>" max="<?=h($requestMaxDate)?>" required><small>선택 가능: 오늘 ~ <?=h($requestMaxDate)?></small></label><label class="col6">종료일<input type="date" name="end_date" min="<?=h(date('Y-m-d'))?>" max="<?=h($requestMaxDate)?>" required></label><label class="col6">사용일수<input type="number" step=".25" name="requested_days" value="1" required></label><label class="col6">오전/오후<select name="half_option"><option value="">해당없음</option><option>오전</option><option>오후</option></select></label></div><label>참고사항<textarea name="memo" placeholder="사유 또는 참고사항"></textarea></label><button class="btn">신청 제출</button></form></section><section class="col6"><div class="card"><h2>일자별 신청현황</h2><p class="muted">오늘부터 향후 <?=h($requestPeriodLabel)?>의 승인대기·승인 현황입니다.</p><?php if(!$by):?><p>등록된 일정이 없습니다.</p><?php endif?><?php foreach($by as $d=>$items):?><div class="calendar-day"><strong><?=h($d)?> (<?=['일','월','화','수','목','금','토'][date('w',strtotime($d))]?>)</strong><?php foreach($items as $r):?><div><span style="color:<?=h($r['color'])?>">●</span> <?=h($r['name'].' '.$r['position'])?> · <?=h($r['leave_name'])?> <?=h($r['half_option'])?> <span class="badge"><?=h($r['status']==='approved'?'승인':'결재중')?></span></div><?php endforeach?></div><?php endforeach?></div></section></div></main><script>const t=document.querySelector('#leave_type');t?.addEventListener('change',()=>{const o=t.selectedOptions[0];if(!o)return;document.querySelector('[name=requested_days]').value=o.dataset.days||1;document.querySelector('[name=end_date]').disabled=o.dataset.range==='0';document.querySelector('[name=half_option]').disabled=o.dataset.half==='0';});</script></body></html>